#include <vector>
#include <string>
#include <set>

using namespace std;

class Solution {
private:
    set<string> parse(const string& expr, int& i) {
        set<string> currentGroup;
        set<string> term;
        term.insert(""); // Start with an empty string for concatenation

        while (i < expr.length() && expr[i] != '}') {
            if (expr[i] == ',') {
                // Union the current term into currentGroup and reset term
                currentGroup.insert(term.begin(), term.end());
                term = {""};
                i++;
            } else if (expr[i] == '{') {
                i++; // skip '{'
                set<string> inner = parse(expr, i);
                // Concatenate inner set with current term
                set<string> nextTerm;
                for (const string& a : term) {
                    for (const string& b : inner) {
                        nextTerm.insert(a + b);
                    }
                }
                term = nextTerm;
            } else {
                // It's a letter
                string letter = "";
                letter += expr[i++];
                set<string> nextTerm;
                for (const string& a : term) {
                    nextTerm.insert(a + letter);
                }
                term = nextTerm;
            }
        }
        if (i < expr.length() && expr[i] == '}') {
            i++; // skip '}'
        }
        currentGroup.insert(term.begin(), term.end());
        return currentGroup;
    }

public:
    vector<string> braceExpansionII(string expression) {
        // Wrap the expression in braces to make it a single term/group for parsing
        string expr = "{" + expression + "}";
        int i = 0;
        set<string> result = parse(expr, i);
        return vector<string>(result.begin(), result.end());
    }
};
